module lamberts_ellipsoidal_distance
import math
@[export: 'lamberts_ellipsoidal_distance']
pub fn lamberts_ellipsoidal_distance(v &i64,n usize)f64{if n!=4{return -1e300};for i in 0..4{x:=unsafe{v[i]};if (i%2==0&&(x < -90000000||x>90000000))||(i%2==1&&(x < -180000000||x>180000000)){return -1e300}};if unsafe{v[0]}==unsafe{v[2]}&&unsafe{v[1]}==unsafe{v[3]}{return -1e300};pi:=3.14159265358979323846264338327950288;lat1:=f64(unsafe{v[0]})/1e6;lon1:=f64(unsafe{v[1]})/1e6;lat2:=f64(unsafe{v[2]})/1e6;lon2:=f64(unsafe{v[3]})/1e6;p1:=lat1*pi/180;p2:=lat2*pi/180;l1:=lon1*pi/180;l2:=lon2*pi/180;h:=math.sqrt(math.pow(math.sin((p2-p1)/2),2)+math.cos(p1)*math.cos(p2)*math.pow(math.sin((l2-l1)/2),2));if h==0{return -1e300};sigma:=2*math.asin(h);f:=(6378137.0-6356752.314245)/6378137.0;b1:=math.atan((1-f)*math.tan(lat1*pi/180));b2:=math.atan((1-f)*math.tan(lat2*pi/180));p:=(b1+b2)/2;q:=(b2-b1)/2;x:=(sigma-math.sin(sigma))*((math.pow(math.sin(p),2)*math.pow(math.cos(q),2))/math.pow(math.cos(sigma/2),2));y:=(sigma+math.sin(sigma))*((math.pow(math.cos(p),2)*math.pow(math.sin(q),2))/math.pow(math.sin(sigma/2),2));return 6378137.0*(sigma-(f/2)*(x+y))}
